import backtrader as bt


class ADXStochasticStrategy(bt.Strategy):
    def __init__(self):
        self.dmi = bt.indicators.DirectionalMovementIndex(self.data, period=14)
        self.stochastic = bt.indicators.StochasticFull(
            self.data, period=14, period_dfast=3, period_dslow=3
        )
        self.full_k = self.stochastic.percD
        self.order = None
        self.stop_order = None

    def next(self):
        if self.order is not None:
            return

        adx_crossed_below = self.dmi.adx[-1] > 25 and self.dmi.adx[0] < 25

        if self.position:
            if adx_crossed_below:
                if self.stop_order is not None:
                    self.cancel(self.stop_order)
                self.order = self.close()
            return

        if self.stop_order is not None:
            return

        if self.dmi.adx[0] > 25:
            bullish_bias = self.dmi.plusDI[0] > self.dmi.minusDI[0]
            bearish_bias = self.dmi.minusDI[0] > self.dmi.plusDI[0]
            k_crossed_below_20 = self.full_k[-1] > 20 and self.full_k[0] < 20
            k_crossed_above_80 = self.full_k[-1] < 80 and self.full_k[0] > 80

            if bullish_bias and k_crossed_below_20:
                self.order = self.buy()
            elif bearish_bias and k_crossed_above_80:
                self.order = self.sell()

    def notify_order(self, order):
        if order.status in (order.Submitted, order.Accepted):
            return

        if order is self.stop_order:
            if order.status in (
                order.Completed,
                order.Canceled,
                order.Margin,
                order.Rejected,
            ):
                self.stop_order = None
            return

        if order is self.order:
            if order.status == order.Completed and self.position:
                if self.position.size > 0:
                    stop_price = self.position.price * (1 - 0.02)
                    self.stop_order = self.sell(
                        size=abs(self.position.size),
                        exectype=bt.Order.Stop,
                        price=stop_price,
                    )
                else:
                    stop_price = self.position.price * (1 + 0.02)
                    self.stop_order = self.buy(
                        size=abs(self.position.size),
                        exectype=bt.Order.Stop,
                        price=stop_price,
                    )

            if order.status in (
                order.Completed,
                order.Canceled,
                order.Margin,
                order.Rejected,
            ):
                self.order = None
